begin;select plan(19);
select has_table('public','push_subscriptions','push devices exist');select col_is_unique('public','push_subscriptions','endpoint','endpoint unique');select col_is_unique('public','push_subscriptions','endpoint_hash','endpoint hash unique');select col_type_is('public','notification_deliveries','channel','text','deliveries share channel model');select has_column('public','notification_deliveries','push_subscription_id','push delivery references device');
select has_function('public','register_push_subscription',array['text','text','text','text','text','text'],'registration function');select has_function('public','revoke_push_subscription',array['uuid'],'revocation function');select ok((select relrowsecurity from pg_class where oid='public.push_subscriptions'::regclass),'push RLS enabled');
select is((select count(*)::integer from information_schema.columns where table_schema='public' and table_name='push_subscription_metadata' and column_name in('endpoint','endpoint_hash','p256dh','auth')),0,'metadata view exposes no keys');select is((select count(*)::integer from information_schema.tables where table_schema='public' and table_name='push_notification_events'),0,'no parallel event table');
set local role authenticated;select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000701',true);
select throws_ok($$select public.register_push_subscription('bad','bad','bad','','web',null)$$,'22023',null,'invalid subscription rejected');select is((select count(*)::integer from public.push_subscription_metadata),0,'customer cannot see other device metadata');select throws_ok($$insert into public.notification_preferences(customer_id,channel,category,enabled)values('00000000-0000-0000-0000-000000000701','push','transactional',false)$$,'42501',null,'mandatory transactional push cannot be disabled');
select ok(position('customer_id=auth.uid()' in replace(pg_get_functiondef('public.revoke_push_subscription(uuid)'::regprocedure),' ',''))>0,'revocation owner scoped');select ok((select indexdef like '%push_subscription_id%' from pg_indexes where indexname='notification_delivery_channel_attempt_unique'),'delivery idempotency includes device');select ok((select count(*) from pg_policies where tablename='push_subscriptions' and policyname='push_own_read')=1,'own read policy exists');select is((select count(*)::integer from public.notification_events),0,'push reuses event outbox');
select ok((select count(*) from information_schema.columns where table_name='push_subscription_metadata')>=7,'admin metadata view exists');select ok((select count(*) from pg_indexes where tablename='push_subscriptions')>=3,'device indexes exist');select * from finish();rollback;
